package mz.uem.restaurante.ui;
import java.awt.*; import javax.swing.*; import javax.swing.table.DefaultTableModel; import mz.uem.restaurante.service.DadosSistema;
public class PainelAuditoria extends JPanel {
 private DadosSistema dados; private final JTextField pesquisa=new JTextField(18); private final DefaultTableModel modelo=new DefaultTableModel(new Object[]{"Data/Hora","Utilizador","Operação","Entidade","Detalhe"},0){public boolean isCellEditable(int r,int c){return false;}}; private final JTable tabela=new JTable(modelo);
 public PainelAuditoria(){setLayout(new BorderLayout(0,14));setBorder(BorderFactory.createEmptyBorder(20,24,20,24));JPanel topo=new JPanel(new BorderLayout(8,8));topo.setOpaque(false);topo.add(Ui.titulo("Auditoria do sistema"),BorderLayout.WEST);topo.add(pesquisa,BorderLayout.EAST);Ui.prepararTabela(tabela);JScrollPane scroll=new JScrollPane(tabela);Ui.card(scroll);JButton actualizar=Ui.botaoSecundario("Actualizar");actualizar.addActionListener(e->actualizar());pesquisa.addActionListener(e->filtrar());add(topo,BorderLayout.NORTH);add(scroll,BorderLayout.CENTER);add(actualizar,BorderLayout.SOUTH);}
 public void setDados(DadosSistema d){dados=d;actualizar();} private void actualizar(){modelo.setRowCount(0);if(dados!=null)dados.auditoriaService.listar().forEach(x->modelo.addRow(new Object[]{x.getDataHora(),x.getUtilizador(),x.getOperacao(),x.getEntidade(),x.getDetalhe()}));filtrar();} private void filtrar(){String f=pesquisa.getText().trim().toLowerCase();for(int i=modelo.getRowCount()-1;i>=0;i--){boolean ok=f.isEmpty();for(int c=1;c<5&&!ok;c++)ok=String.valueOf(modelo.getValueAt(i,c)).toLowerCase().contains(f);if(!ok)modelo.removeRow(i);}}
}
